public static int[] diagonalOrder(int[][] mat) {
    // Initialize an array to store the resulting diagonal order
    int[] result = new int[mat.length * mat[0].length];
    // Initialize variables to keep track of the current index and the current diagonal
    int idx = 0, diagonal = 0;
    // Loop through each element in the matrix
    for (int row = 0; row < mat.length; row++) {
        for (int col = 0; col < mat[0].length; col++) {
            // If we are on the main diagonal (top-left to bottom-right), add the element and increment the index
            if (row == col) {
                result[idx++] = mat[row][col];
            }
            // If we are on the diagonal below the main diagonal (top-right to bottom-left), add the element and increment the index
            else if (row + col == mat[0].length - 1) {
                result[idx++] = mat[row][col];
            }
            // If we are on the left or right side of the diagonal (left-to-right and top-to-bottom), skip the element and do not increment the index
            else {
                continue;
            }
        }
        // Once we reach the end of the row, increment the diagonal
        diagonal++;
    }
    // Return the resulting diagonal order array
    return result;
}
